// ── Image fetcher: convert /manus-storage/ URLs to base64 for Puppeteer ──────
async function fetchImageAsBase64(url: string): Promise<string> {
  if (!url) return "";
  try {
    // Handle /manus-storage/ paths by fetching from local server
    let fetchUrl = url;
    if (url.startsWith("/manus-storage/")) {
      // Use the forge API to get a presigned URL
      const forgeBaseUrl = (process.env.BUILT_IN_FORGE_API_URL || "").replace(/\/+$/, "");
      const forgeKey = process.env.BUILT_IN_FORGE_API_KEY;
      if (forgeBaseUrl && forgeKey) {
        const key = url.replace(/^\/manus-storage\//, "");
        const forgeUrl = new URL("v1/storage/presign/get", forgeBaseUrl + "/");
        forgeUrl.searchParams.set("path", key);
        const forgeResp = await fetch(forgeUrl.toString(), {
          headers: { Authorization: `Bearer ${forgeKey}` },
        });
        if (forgeResp.ok) {
          const { url: signedUrl } = await forgeResp.json() as { url: string };
          fetchUrl = signedUrl;
        }
      }
    }
    const resp = await fetch(fetchUrl);
    if (!resp.ok) return "";
    const buf = await resp.arrayBuffer();
    const mime = resp.headers.get("content-type") || "image/jpeg";
    const b64 = Buffer.from(buf).toString("base64");
    return `data:${mime};base64,${b64}`;
  } catch {
    return "";
  }
}

