// ── دالة مساعدة: شريط KPI ─────────────────────────────────────────────────
function kpiBar(kpis: {v:string,l:string}[], bg: string, numColor: string, lblColor: string, border: string) {
  return `<div style="display:grid;grid-template-columns:repeat(${kpis.length},1fr);gap:0;border:1px solid ${border};border-radius:4px;overflow:hidden">
    ${kpis.map((k,i) => `<div style="background:${bg};padding:10px 6px;text-align:center;${i>0?`border-right:1px solid ${border}`:''}">
      <div style="font-size:18px;font-weight:900;color:${numColor};line-height:1">${k.v}</div>
      <div style="font-size:7px;color:${lblColor};margin-top:3px;font-weight:600">${k.l}</div>
    </div>`).join("")}
  </div>`;
}

// ── دالة مساعدة: شريط مرافق ───────────────────────────────────────────────
function amenityTags(list: string[], bg: string, color: string, border: string) {
  return list.slice(0,8).map(a =>
    `<span style="background:${bg};border:1px solid ${border};color:${color};font-size:7px;padding:3px 8px;border-radius:20px;font-weight:600;white-space:nowrap">${a}</span>`
  ).join("");
}

