function footer(page: string, bg: string, textColor: string, accentColor: string) {
  return `<div style="height:36px;flex-shrink:0;background:${bg};display:flex;align-items:center;justify-content:space-between;padding:0 28px;border-top:2px solid ${accentColor}">
    <div style="font-size:7px;color:${textColor};opacity:0.6">شركة دلمون للاستثمار · DELMON INVESTMENT COMPANY</div>
    <div style="font-size:7px;color:${accentColor};font-weight:700">صفحة ${page}</div>
    <div style="font-size:7px;color:${textColor};opacity:0.6">www.delmoninvest.com</div>
  </div>`;
}

