// ─── تصحيح إملائي تلقائي للأخطاء الشائعة في النصوص العربية ───
function autoCorrectArabic(text: string): string {
  if (!text) return text;
  const corrections: [RegExp, string][] = [
    [/حرعسات\s*امنية/g, "حراسات أمنية"],
    [/حرعسات\s*أمنية/g, "حراسات أمنية"],
    [/حراسات\s*امنية/g, "حراسات أمنية"],
    [/نماص\s*ليلي/g, "إنارة ليلية"],
    [/نماص\s*لليلي/g, "إنارة ليلية"],
    [/نماص/g, "إنارة"],
    [/\s*\.\.\.\s*يتميز\s*لب\s*\.\.\.\s*$/g, ""],
    [/\s*يتميز\s*لب\s*\.\.\.\s*$/g, ""],
    [/\s*\.\.\.\s*$/g, ""],
    [/مواقف\s*سياره/g, "مواقف سيارات"],
    [/كهرباء\s*احتياطيه/g, "كهرباء احتياطية"],
    [/مصعد\s*بانورامى/g, "مصعد بانورامي"],
  ];
  let result = text;
  for (const [pattern, replacement] of corrections) {
    result = result.replace(pattern, replacement);
  }
  return result.trim();
}

function buildBrochureHTML(data: ProjectData, template: string): string {
  // تطبيق التصحيح الإملائي التلقائي على النصوص قبل التوليد
  data = { ...data, description: autoCorrectArabic(data.description || ""), amenities: autoCorrectArabic(data.amenities || ""), projectName: autoCorrectArabic(data.projectName || "") };
  const amenitiesList = data.amenities
    ? data.amenities.split(/[,،\n]/).map((s: string) => s.trim()).filter(Boolean)
    : [];
  const DEFAULT_AMENITIES = ["موقف سيارات متعدد الطوابق", "أنظمة أمن متطورة", "مصاعد بانورامية", "مولدات طاقة احتياطية", "نظام تكييف مركزي", "خدمات صيانة متكاملة"];
  const finalAmenitiesList = amenitiesList.length > 0 ? amenitiesList : DEFAULT_AMENITIES;

  const imgSrc = data.projectImage || DEFAULT_IMG_B64;

  // Normalize units: الواجهة ترسل data.units كـ array، لكن محرك PDF يقرأ data.units_list
  // نوحّد الحقلين هنا ونعالج أسماء الحقول المختلفة
  let unitsList: Unit[] = [];
  if (Array.isArray(data.units_list) && data.units_list.length > 0) {
    unitsList = data.units_list;
  } else if (Array.isArray(data.units) && data.units.length > 0) {
    unitsList = data.units as Unit[];
  }
  // Normalize unit fields: الواجهة ترسل type وprice، لكن محرك PDF يقرأ unitType وmonthlyRent
  unitsList = unitsList.map((u: Unit) => ({
    ...u,
    unitType: u.unitType || (u as any).type || "",
    monthlyRent: u.monthlyRent !== undefined ? u.monthlyRent : ((u as any).price || ""),
  }));

  // Normalize features: accept both string and string[]
  const featuresStr: string | undefined = Array.isArray(data.features)
    ? (data.features as string[]).join(",")
    : (data.features as string | undefined);
  const normalizedData = { ...data, features: featuresStr, units_list: unitsList };

  const kpis = [
    { v: data.totalArea ? Number(String(data.totalArea).replace(/,/g, "")).toLocaleString("en-US") + " م²" : "—" as string, l: "المساحة" },
    { v: String(data.floors || "—"), l: "الطوابق" },
    { v: unitsList.length > 0 ? String(unitsList.length) : "—", l: "الوحدات" },
    { v: String(data.completionYear || "—"), l: "الإنجاز" },
  ];

  let p1: string;
  if (template === "dark") p1 = darkPage1(normalizedData, finalAmenitiesList, kpis, imgSrc);
  else if (template === "magazine") p1 = magazinePage1(normalizedData, finalAmenitiesList, kpis, imgSrc);
  else p1 = classicPage1(normalizedData, finalAmenitiesList, kpis, imgSrc);

  const p2 = page2(normalizedData, template, finalAmenitiesList);
  const p3 = page3(normalizedData, template);
  const p4 = page4(normalizedData, template);
  const p5 = page5(normalizedData, template, imgSrc, finalAmenitiesList);
  const p6 = page6(normalizedData, template, imgSrc);
  const p7 = page7(normalizedData, template);
  const p8 = page8(normalizedData, template);
  const p9 = page9(normalizedData, template);
  const p10 = page10(normalizedData, template, imgSrc);

  return `<!DOCTYPE html>
<html dir="rtl" lang="ar">
<head>
<meta charset="UTF-8">
<style>
@font-face {
  font-family: 'Cairo';
  src: url('data:font/truetype;base64,') format('truetype');
  font-weight: 400;
  font-style: normal;
}
@font-face {
  font-family: 'Cairo';
  src: url('data:font/truetype;base64,') format('truetype');
  font-weight: 600;
  font-style: normal;
}
@font-face {
  font-family: 'Cairo';
  src: url('data:font/truetype;base64,') format('truetype');
  font-weight: 700 800 900;
  font-style: normal;
}
</style>
<style>
@page { size: 1123px 794px; margin: 0; }
:root {
  --sp-1: 8px;
  --sp-2: 16px;
  --sp-3: 24px;
  --sp-4: 32px;
  --sp-5: 40px;
  --sp-6: 48px;
  --radius-sm: 4px;
  --radius-md: 8px;
  --radius-lg: 12px;
}
* { margin: 0; padding: 0; box-sizing: border-box; }
body { font-family: 'Cairo', sans-serif; direction: rtl; unicode-bidi: bidi-override; }
* { unicode-bidi: isolate; }
[dir="rtl"], .page, .page * { direction: rtl; unicode-bidi: embed; }
.page {
  width: 1123px;
  min-height: 794px;
  display: flex;
  flex-direction: column;
  page-break-after: always;
  break-after: page;
  position: relative;
}
.page-fixed {
  height: 794px;
  max-height: 794px;
  overflow: hidden;
}
.page-body {
  width: 1123px;
  height: 652px;
  display: flex;
  overflow: hidden;
  flex-shrink: 0;
}
.page-body-mag {
  width: 1123px;
  height: 618px;
  display: flex;
  overflow: hidden;
  flex-shrink: 0;
}
</style>
</head>
<body>
${p1}
${p2}
${p3}
${p4}
${p5}
${p6}
${p7}
${p8}
${p9}
${p10}
</body>
</html>`;
}

// ── Express route handler ─────────────────────────────────────────────────────
export async function pdfRouteHandler(req: Request, res: Response) {
  try {
    const { data, template = "classic" } = req.body as {
      data: ProjectData;
      template: string;
    };

    if (!data) {
      res.status(400).json({ error: "Missing data" });
      return;
    }

    // Pre-fetch project image and save to temp file for WeasyPrint (avoids base64 OOM)
    let resolvedData = { ...data };
    if (data.projectImage && data.projectImage.startsWith("/manus-storage/")) {
      const b64 = await fetchImageAsBase64(data.projectImage);
      if (b64) resolvedData.projectImage = b64;
    }
    // If image is base64, write to temp file and replace with file:// URL
    let tmpImagePath: string | null = null;
      if (resolvedData.projectImage && resolvedData.projectImage.startsWith("data:image")) {
        try {
          const sepIdx = resolvedData.projectImage.indexOf(",");
          const header = sepIdx > 0 ? resolvedData.projectImage.slice(0, sepIdx) : "";
          const b64Data = sepIdx > 0 ? resolvedData.projectImage.slice(sepIdx + 1) : "";
          const mimeMatch = header.match(/^data:(image\/[\w]+);base64$/);
          const match = mimeMatch && b64Data ? [null, mimeMatch[1], b64Data] : null;
          if (match) {
            const mimeStr = (match[1] as string) || "image/jpeg";
            const ext = mimeStr.replace("image/", "").replace("jpeg", "jpg");
            tmpImagePath = path.join(os.tmpdir(), `delmon_img_${Date.now()}.${ext}`);
            fsSync.writeFileSync(tmpImagePath, Buffer.from(match[2] as string, "base64"));
            resolvedData.projectImage = `file://${tmpImagePath}`;
          }
        } catch {}
      }
    const html = buildBrochureHTML(resolvedData, template);

    // ── WeasyPrint PDF generation (serverless-safe, no Chromium OOM) ──
    const pdfBuffer = await generatePDFWithPuppeteer(html);

    // Clean up temp image file
    if (tmpImagePath) { try { fsSync.unlinkSync(tmpImagePath); } catch {} }

    const projectName = data.projectName || "بروشور-دلمون";
    const city = data.city ? `-${data.city}` : "";
    const date = new Date().toISOString().split("T")[0];
    const filename = encodeURIComponent(`بروشور-دلمون-${projectName}${city}-${date}.pdf`);

    res.setHeader("Content-Type", "application/pdf");
    res.setHeader("Content-Disposition", `attachment; filename*=UTF-8\'\'${filename}`);
    const buf = Buffer.isBuffer(pdfBuffer) ? pdfBuffer : Buffer.from(pdfBuffer);
    res.setHeader("Content-Length", buf.length);
    res.end(buf);
  } catch (err) {
    console.error("[PDF Route Error]", err);
    res.status(500).json({ error: "فشل توليد PDF", details: String(err) });
  }
}

// ── Puppeteer PDF helper ──────────────────────────────────────────────────────
async function generatePDFWithPuppeteer(html: string): Promise<Buffer> {
  // Serialize PDF generation to avoid concurrent Chromium memory spikes
  await acquirePdfMutex();
  try {
    const browser = await getBrowser();
    const page = await browser.newPage();
    try {
      await page.setContent(html, { waitUntil: "load", timeout: 90000 });
      await new Promise(r => setTimeout(r, 1000));
      const pdf = await page.pdf({
        format: "A4",
        printBackground: true,
        margin: { top: 0, right: 0, bottom: 0, left: 0 },
        timeout: 90000,
      });
      return Buffer.from(pdf);
    } finally {
      await page.close().catch(() => {});
    }
  } finally {
    releasePdfMutex();
  }
}
